import { cn } from "@/shared/lib/utils";
import React from "react";

interface GlassCardProps extends React.HTMLAttributes<HTMLDivElement> {
    children: React.ReactNode;
    className?: string;
    gradient?: boolean;
}

export const GlassCard = ({ children, className, gradient = true, variant = "default", ...props }: GlassCardProps & { variant?: "default" | "premium" }) => {
    const isPremium = variant === "premium";

    return (
        <div
            className={cn(
                "relative overflow-hidden transition-all",
                // Base styles
                "border shadow-sm",
                // Default Variant
                !isPremium && "rounded-2xl bg-white/40 dark:bg-black/20 backdrop-blur-md border-white/20 dark:border-white/10 hover:shadow-md",
                // Premium Variant (Apple-style widget)
                isPremium && [
                    "rounded-[2rem]",
                    "bg-white/60 dark:bg-black/20",
                    "backdrop-blur-xl saturate-150",
                    "border-white/50 dark:border-white/10",
                    "shadow-[0_8px_32px_rgba(0,0,0,0.12)]",
                    "hover:shadow-[0_16px_48px_rgba(197,160,101,0.2)]"
                ],
                className
            )}
            {...props}
        >
            {gradient && (
                <div className={cn(
                    "absolute inset-0 pointer-events-none",
                    isPremium
                        ? "bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
                        : "bg-gradient-to-br from-white/20 via-transparent to-transparent"
                )} />
            )}
            <div className="relative z-10">{children}</div>
        </div>
    );
};

