/**
 * Detalhe de uma denúncia e thread de mensagens para o painel das donas.
 *
 * Duas queries paralelas (denúncia + mensagens) para invalidação granular.
 * Ambas ficam sob o mesmo queryKey raiz ['ouvidoria', 'detalhe', id] para
 * facilitar invalidateQueries com prefixo ['ouvidoria'].
 *
 * 'respondido_por' é excluído das mensagens — coluna de auditoria interna
 * que não deve ser exposta na UI.
 */

import { useQuery } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { DenunciaOuvidoria, MensagemThread } from '../types';

const COLUNAS_DENUNCIA =
  'id, protocolo, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em';
const COLUNAS_MENSAGEM = 'autor, mensagem, created_at';

export interface OuvidoriaDetalhe {
  denuncia: DenunciaOuvidoria;
  mensagens: MensagemThread[];
}

export function useOuvidoriaDetalhe(denunciaId?: string) {
  return useQuery<OuvidoriaDetalhe>({
    queryKey: ['ouvidoria', 'detalhe', denunciaId],
    enabled: Boolean(denunciaId),
    queryFn: async () => {
      const [denunciaRes, mensagensRes] = await Promise.all([
        supabase
          .from('ouvidoria_denuncias' as any) // tabela tipada via schema gerado
          .select(COLUNAS_DENUNCIA)
          .eq('id', denunciaId as any)
          .single(),
        supabase
          .from('ouvidoria_mensagens' as any)
          .select(COLUNAS_MENSAGEM)
          .eq('denuncia_id', denunciaId as any)
          .order('created_at', { ascending: true }),
      ]);

      if (denunciaRes.error) throw new Error(denunciaRes.error.message);
      if (mensagensRes.error) throw new Error(mensagensRes.error.message);

      return {
        denuncia: denunciaRes.data as unknown as DenunciaOuvidoria,
        mensagens: (mensagensRes.data ?? []) as unknown as MensagemThread[],
      };
    },
  });
}

