/**
 * Mutation para as donas atualizarem o status de uma denúncia.
 *
 * Workflow permitido: recebida → em_analise → resolvida → arquivada.
 * A RPC `atualizar_status_ouvidoria` valida o acesso (can_view_ouvidoria)
 * e qualquer transição de status inválida no banco.
 *
 * Invalida toda a árvore ['ouvidoria'] para que lista e detalhe reflitam
 * o novo status imediatamente.
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import { supabase } from '@/integrations/supabase/client';
import type { AtualizarStatusInput } from '../types';

interface RpcResult {
  ok: boolean;
  erro?: string;
}

export function useAtualizarStatusOuvidoria() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (input: AtualizarStatusInput): Promise<void> => {
      const { data, error } = await supabase.rpc('atualizar_status_ouvidoria', {
        p_denuncia_id: input.denuncia_id,
        p_status: input.status,
      });
      if (error) throw new Error(error.message);

      const result = data as unknown as RpcResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Não foi possível atualizar o status.');
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['ouvidoria'] });
    },
    onError: (err: Error) => {
      toast.error(err.message);
    },
  });
}

