 *
 * A RPC `marcar_ouvidoria_lida` retorna void (undefined no JS). Invalida
 * o contador de não-lidas (queryKey ['ouvidoria', 'unread']) e o detalhe
 * da denúncia para que o badge suma imediatamente.
 */

import { useMutation, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

export function useMarcarOuvidoriaLida() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (denunciaId: string): Promise<void> => {
      const { error } = await supabase.rpc('marcar_ouvidoria_lida', {
        p_denuncia_id: denunciaId,
      });
      if (error) throw new Error(error.message);
