    onSuccess: () => {
      // Invalida o contador de não-lidas e o detalhe da denúncia
      queryClient.invalidateQueries({ queryKey: ['ouvidoria', 'unread'] });
      queryClient.invalidateQueries({ queryKey: ['ouvidoria', 'list'] });
    },
  });
}

