/**
 * Painel interno de ouvidoria — restrito às proprietárias.
 * Gate via useOuvidoriaAccess (RPC can_view_ouvidoria).
 */

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Shield,
  Inbox,
  AlertCircle,
  CheckCircle2,
  Archive,
  Filter,
  X,
  Lock,
  Dot,
} from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';

import { Button } from '@/shared/ui/button';
import { GlassCard } from '@/shared/ui/glass-card';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { TelemetryErrorBoundary } from '@/shared/ui/TelemetryErrorBoundary';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/shared/ui/table';

import { CATEGORIAS_OUVIDORIA, STATUS_OUVIDORIA } from '../lib/categorias';
import { LOJAS_OUVIDORIA, nomeLoja } from '../lib/lojas';
import { useOuvidoriaAccess } from '../model/useOuvidoriaAccess';
import { useOuvidoriaList } from '../model/useOuvidoriaList';
import { useOuvidoriaUnreadCount } from '../model/useOuvidoriaUnreadCount';
import { StatusBadge } from './StatusBadge';
import { CategoriaBadge } from './CategoriaBadge';
import type { CategoriaOuvidoria, DenunciaOuvidoria, OuvidoriaFiltros, StatusOuvidoria } from '../types';

// ---------------------------------------------------------------------------
// Componente de KPI card
// ---------------------------------------------------------------------------

interface KpiCardProps {
  icon: React.ReactNode;
  label: string;
  value: number;
  highlight?: boolean;
}

function KpiCard({ icon, label, value, highlight }: KpiCardProps) {
  return (
    <div className="relative group bg-white/60 dark:bg-[#1A1A1A]/60 rounded-[2rem] p-5 border border-[#57715B]/10 shadow-sm hover:shadow-md backdrop-blur-md transition-all overflow-hidden">
      <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity pointer-events-none">
        <div className="h-12 w-12 text-[#57715B]">{icon}</div>
      </div>
      <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
        {label}
      </p>
      <p
        className={`text-2xl font-bold tabular-nums ${
          highlight ? 'text-amber-600' : 'text-[#2D362E] dark:text-[#E6DCCF]'
        }`}
      >
        {value}
      </p>
