                    <span className="text-xs text-muted-foreground">
                      {format(parseISO(d.created_at), 'dd/MM/yyyy', { locale: ptBR })}
                    </span>
                  </div>
                </GlassCard>
              </button>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Página exportada com gate de acesso
// ---------------------------------------------------------------------------

function OuvidoriaComGate() {
  const { canView, isLoading } = useOuvidoriaAccess();

  if (isLoading) return <SkeletonPainel />;

  if (!canView) {
    return (
      <MommaPageLayout>
        <div className="flex items-center justify-center min-h-[60vh] p-6">
          <GlassCard variant="premium" className="p-8 max-w-sm w-full flex flex-col items-center gap-4 text-center">
            <div className="rounded-2xl bg-[#57715B]/10 p-4">
              <Lock className="h-8 w-8 text-[#57715B]" />
            </div>
            <h2 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Acesso restrito a proprietárias
            </h2>
            <p className="text-sm text-muted-foreground">
              O painel de ouvidoria é acessível apenas às proprietárias da Momma. Entre em
              contato se acredita que deveria ter acesso.
            </p>
          </GlassCard>
        </div>
      </MommaPageLayout>
    );
  }

  return (
    <MommaPageLayout>
      <PainelOuvidoria />
    </MommaPageLayout>
  );
}

export default function OuvidoriaPage() {
  return (
    <TelemetryErrorBoundary moduleName="ouvidoria">
      <OuvidoriaComGate />
    </TelemetryErrorBoundary>
  );
}

